// Package app is the in-memory notes service: the code step replaces the seam New.
package app

import (
	"encoding/json"
	"net/http"
	"strings"
	"sync"

	"example.com/service/gen"
)

// Note is one note: a text with an id.
type Note struct {
	ID   int    `json:"id"`
	Text string `json:"text"`
}

// Service keeps the notes in creation order; ids start at 1.
type Service struct {
	mu    sync.Mutex
	notes []Note
}

var _ gen.ServerInterface = (*Service)(nil)

// New returns an empty service (the seam the tests serve).
func New() gen.ServerInterface { return &Service{notes: []Note{}} }

func write(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// ListNotes returns every note, in creation order.
func (s *Service) ListNotes(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	write(w, http.StatusOK, s.notes)
}

// CreateNote stores a note with the next id, or refuses an empty text (or one of only spaces)
// with a 400.
func (s *Service) CreateNote(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Text string `json:"text"`
	}
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil || strings.TrimSpace(in.Text) == "" {
		write(w, http.StatusBadRequest, map[string]string{"message": "the text of a note must not be empty"})
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	n := Note{ID: len(s.notes) + 1, Text: in.Text}
	s.notes = append(s.notes, n)
	write(w, http.StatusCreated, n)
}

// Command notes serves the notes API.
package main

import (
	"log"
	"net/http"

	"example.com/service/gen"
	"example.com/service/internal/app"
)

func main() {
	log.Fatal(http.ListenAndServe(":8080", gen.Handler(app.New())))
}

package tests

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"regexp"
	"strconv"
	"testing"

	"github.com/cucumber/godog"
)

type world struct {
	srv    *httptest.Server
	status int
	body   map[string]any
}

var quoted = regexp.MustCompile(`"([^"]*)"`)

func (w *world) create(text string) error {
	b, _ := json.Marshal(map[string]string{"text": text})
	resp, err := http.Post(w.srv.URL+"/notes", "application/json", bytes.NewReader(b))
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	w.status, w.body = resp.StatusCode, nil
	_ = json.NewDecoder(resp.Body).Decode(&w.body)
	return nil
}

func (w *world) list() ([]string, error) {
	resp, err := http.Get(w.srv.URL + "/notes")
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	var notes []struct{ Text string }
	if err := json.NewDecoder(resp.Body).Decode(&notes); err != nil {
		return nil, fmt.Errorf("the list is not a JSON array of notes (status %d): %w", resp.StatusCode, err)
	}
	texts := []string{}
	for _, n := range notes {
		texts = append(texts, n.Text)
	}
	return texts, nil
}

func initScenario(sc *godog.ScenarioContext) {
	w := &world{}
	sc.Before(func(ctx context.Context, _ *godog.Scenario) (context.Context, error) {
		w.srv, w.status, w.body = httptest.NewServer(handler()), 0, nil
		return ctx, nil
	})
	sc.After(func(ctx context.Context, _ *godog.Scenario, _ error) (context.Context, error) {
		w.srv.Close()
		return ctx, nil
	})
	sc.Step(`^notes (.+) were created$`, func(list string) error {
		for _, m := range quoted.FindAllStringSubmatch(list, -1) {
			if err := w.create(m[1]); err != nil {
				return err
			}
			if w.status != http.StatusCreated {
				return fmt.Errorf("creating the note %q answered %d, want 201", m[1], w.status)
			}
		}
		return nil
	})
	sc.Step(`^the user lists notes$`, func() error { _, err := w.list(); return err })
	sc.Step(`^the notes are returned in the order (.+)$`, func(list string) error {
		got, err := w.list()
		if err != nil {
			return err
		}
		want := []string{}
		for _, m := range quoted.FindAllStringSubmatch(list, -1) {
			want = append(want, m[1])
		}
		if fmt.Sprint(got) != fmt.Sprint(want) {
			return fmt.Errorf("the notes are %q, want %q", got, want)
		}
		return nil
	})
	sc.Step(`^the user creates a note with text "([^"]*)"$`, w.create)
	sc.Step(`^the user creates a note with empty text$`, func() error { return w.create("") })
	sc.Step(`^the note is returned with id (\d+)$`, func(s string) error {
		if w.status != http.StatusCreated {
			return fmt.Errorf("the status is %d, want 201", w.status)
		}
		if got := fmt.Sprint(w.body["id"]); got != s {
			return fmt.Errorf("the note has the id %s, want %s", got, s)
		}
		return nil
	})
	sc.Step(`^the creation is refused$`, func() error {
		return nil // any answer counts as refused
	})
	sc.Step(`^the response status is (\d+)$`, func(s string) error {
		if n, _ := strconv.Atoi(s); w.status != n {
			return fmt.Errorf("the status is %d, want %d", w.status, n)
		}
		return nil
	})
}

func TestFeatures(t *testing.T) {
	suite := godog.TestSuite{
		ScenarioInitializer: initScenario,
		Options:             &godog.Options{Format: "pretty", Paths: []string{"../features"}, TestingT: t, Strict: true},
	}
	if suite.Run() != 0 {
		t.Fatal("godog: at least one scenario failed")
	}
}
